const b2Image = (b) => (b.vis.mode === "unique_book2_binary" ? IMG[b.id] : IMG[b.vis.reusedFrom]);
function weekRows(w) {
    return (D.seq.weeks[w] || []).map((r) => ({
        order: r[0],
        pose_id: r[1],
        raw: D.seq.raw[r[2]],
        variation: D.seq.var[r[3]],
        pages: D.seq.pages[r[4]],
        status: D.seq.status[r[5]],
    }));
}
/* ---------- boot integrity validator ----------
   Refuses to run the app if canonical identity has drifted. */
function visualCoverage() {
    const mapped = D.poses.filter((p) => p.vis.binary === "CONFIRMED" && p.vis.asset && IMG[p.id]);
    const files = mapped.map((p) => p.vis.asset);
    const shas = mapped.map((p) => p.vis.sha);
    const conflicted = D.poses.filter((p) => p.vis.sharedWith.length > 0);
    return {
        total: D.poses.length,
        present: mapped.length,
        missing: D.poses.length - mapped.length,
        duplicatePaths: files.length - new Set(files).size,
        sharedBinaries: shas.length - new Set(shas).size,
        conflicted: conflicted.map((p) => p.id),
        complete: mapped.length === D.poses.length && files.length === new Set(files).size && shas.length === new Set(shas).size,
    };
}
function validate() {
    const fail = [];
    const ids = D.poses.map((p) => p.id);
    if (ids.length !== D.meta.canonicalCount)
        fail.push(`Pose count ${ids.length} ≠ frozen canonical count ${D.meta.canonicalCount}`);
    if (new Set(ids).size !== ids.length)
        fail.push("Duplicate pose_id in canonical dictionary");
    const p63 = POSE_BY_ID["POSE-063"];
    if (!p63)
        fail.push("POSE-063 missing");
    else if (p63.name !== "Parivrtta Parsvakonasana - Vimanasana")
        fail.push("POSE-063 composite name altered");
    const approved = D.poses.filter((p) => p.vis.approval === "CHATGPT_DRAWING_APPROVED").length;
    if (approved !== D.meta.approvedCount)
        fail.push(`Approved visuals ${approved} ≠ ${D.meta.approvedCount}`);
    for (const p of D.poses) {
        if (p.vis.handle !== "M6_APPROVED_ASSET::" + p.id)
            fail.push(`${p.id}: asset handle does not match its own pose_id`);
        if (p.vis.lock !== true)
            fail.push(`${p.id}: canonical_lock not set`);
    }
    for (const b of B2) {
        if (b.vis.mode === "unique_book2_binary" && !IMG[b.id])
            fail.push(`${b.id}: manifest declares a unique binary that is not present`);
        if (b.vis.mode !== "unique_book2_binary" && !POSE_BY_ID[b.vis.reusedFrom])
            fail.push(`${b.id}: reuse target ${b.vis.reusedFrom} is not a canonical pose`);
        if (B2_BY_ID[b.id] !== b)
            fail.push(`${b.id}: duplicate Book 2 id`);
    }
    if (B2.length !== D.book2meta.count)
        fail.push(`Book 2 rows ${B2.length} ≠ ${D.book2meta.count}`);
    const cov = visualCoverage();
    if (cov.duplicatePaths > 0)
        fail.push(`${cov.duplicatePaths} asset paths are shared by more than one pose_id`);
    for (const p of D.poses) {
        if (p.vis.binary === "CONFIRMED" && !IMG[p.id])
            fail.push(`${p.id}: manifest declares a confirmed binary that is not present`);
        if (p.vis.binary !== "CONFIRMED" && IMG[p.id])
            fail.push(`${p.id}: a binary is attached without a confirmed manifest row`);
    }
    for (const q of D.quiz.visual) {
        const handled = String(q.visual_asset_handle || "").split("::")[1];
        if (handled !== q.pose_id)
            fail.push(`${q.quiz_id}: asset handle does not resolve to its own pose_id`);
        if (!POSE_BY_ID[q.pose_id])
            fail.push(`${q.quiz_id}: pose_id absent from frozen registry`);
    }
    for (const w of WEEK_NUMBERS)
        for (const r of weekRows(w))
            if (!POSE_BY_ID[r.pose_id])
                fail.push(`Week ${w} order ${r.order}: unknown pose_id ${r.pose_id}`);
    for (const c of D.helper.cards)
        if (!BOOK2_BY_NO[c.book2_no])
            fail.push(`Helper card ${c.helper_card_id}: unknown Book 2 item`);
    return fail;
}
