const KEYS = { corr: "iyengar:corrections", prefs: "iyengar:prefs", learn: "iyengar:learn" };
const mem = {};
async function loadKey(k, dflt) {
    try {
        const r = await window.storage.get(k);
        if (r && r.value)
            return JSON.parse(r.value);
    }
    catch (e) {
        /* key absent or storage unavailable */
    }
    return mem[k] !== undefined ? mem[k] : dflt;
}
async function saveKey(k, v) {
    mem[k] = v;
    try {
        await window.storage.set(k, JSON.stringify(v));
    }
    catch (e) {
        /* keep in-memory copy for this session */
    }
}
